import{_ as e,o as r,c as o,a3 as s}from"./chunks/framework.CZBGEXos.js";const n="/manual/img/firmas/mis-firmas.png",i="/manual/img/firmas/nueva-solicitud.png",f=JSON.parse('{"title":"Firmas Digitales","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/firmas.md","filePath":"modulos/firmas.md"}'),t={name:"modulos/firmas.md"};function l(d,a,c,u,m,g){return r(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="firmas-digitales" tabindex="-1">Firmas Digitales <a class="header-anchor" href="#firmas-digitales" aria-label="Permalink to &quot;Firmas Digitales&quot;">​</a></h1><p>Las <strong>firmas digitales</strong> son el corazón del cumplimiento &quot;sin papeleo&quot;. En lugar de imprimir un documento, juntarlo con la firma de cada trabajador y archivarlo en una carpeta, en la plataforma cada persona <strong>firma con su PIN personal</strong> directamente desde su teléfono o computador. Cada firma queda registrada con fecha, hora y un código de verificación que permite comprobar después que fue real.</p><p>Hay tres pantallas relacionadas con firmas, según lo que necesites hacer:</p><ul><li><strong>Mis Firmas</strong> — para que <strong>tú firmes</strong> lo que te asignaron.</li><li><strong>Solicitudes de Firma</strong> — para <strong>pedir firmas</strong> a otras personas (roles de gestión).</li><li><strong>Firmas Offline</strong> — para <strong>recolectar firmas sin conexión</strong> a internet, por ejemplo en terreno donde no hay señal.</li></ul><blockquote><p>🔐 <strong>Tu PIN es tu firma.</strong> Es un código personal de <strong>4 dígitos</strong> que solo tú conoces. Al ingresarlo confirmas que leíste y comprendiste el documento. No lo compartas con nadie: equivale a tu firma de puño y letra.</p></blockquote><h2 id="mis-firmas-—-firmar-lo-que-me-asignaron" tabindex="-1">Mis Firmas — firmar lo que me asignaron <a class="header-anchor" href="#mis-firmas-—-firmar-lo-que-me-asignaron" aria-label="Permalink to &quot;Mis Firmas — firmar lo que me asignaron&quot;">​</a></h2><p>Esta es la pantalla que más usará un <strong>Trabajador</strong>. Aquí aparecen los documentos que esperan tu firma.</p><ol><li>En el menú lateral, entra a <strong>Mis Firmas</strong>.</li><li>Verás la lista de documentos <strong>pendientes de firmar</strong>. Si no tienes ninguno, aparecerá el mensaje <strong>&quot;Todo al día&quot;</strong>.</li><li>Haz clic en el documento que quieres firmar para revisarlo.</li><li>Se abrirá la ventana <strong>Firma digital</strong>. Lee el documento.</li><li>Ingresa tu <strong>PIN de 4 dígitos</strong> y haz clic en <strong>Confirmar Firma</strong>.</li></ol><p><img src="'+n+'" alt="Pantalla Mis Firmas con los documentos pendientes de firmar"></p><p>Una vez firmado, el documento pasa a tu <strong>historial de firmas</strong>, donde cada firma muestra su estado (<strong>Válida</strong>, <strong>Disputada</strong>), la <strong>fecha y hora</strong>, <strong>quién la solicitó</strong>, los <strong>documentos</strong> firmados y un <strong>token de verificación</strong> (el código que prueba la firma).</p><h2 id="solicitudes-de-firma-—-pedir-firmas-a-otros" tabindex="-1">Solicitudes de Firma — pedir firmas a otros <a class="header-anchor" href="#solicitudes-de-firma-—-pedir-firmas-a-otros" aria-label="Permalink to &quot;Solicitudes de Firma — pedir firmas a otros&quot;">​</a></h2><p>Esta pantalla es para los roles de gestión que necesitan que un grupo de personas firme un documento (por ejemplo, la difusión de un procedimiento o la entrega de un EPP).</p><ol><li>Entra a <strong>Solicitudes de Firma</strong> y haz clic en <strong>Nueva Solicitud de Firma</strong>.</li><li>El asistente te guía por pasos: <ul><li><strong>Firmantes</strong> — selecciona quiénes deben firmar (al menos una persona).</li><li><strong>Tipo</strong> — el tipo de solicitud.</li><li><strong>Título</strong> <em>(opcional)</em> — un nombre para identificarla.</li><li><strong>Fecha Límite</strong> <em>(opcional)</em> — hasta cuándo deben firmar.</li><li><strong>Descripción</strong> <em>(opcional)</em> — contexto para los firmantes.</li><li><strong>Archivos</strong> — sube el o los documentos (PDF, Word, Excel o imágenes, máx. 10 MB cada uno).</li></ul></li><li>Crea la solicitud. Cada firmante la recibirá como <strong>pendiente</strong> en su pantalla de <em>Mis Firmas</em> y en su <a href="/manual/modulos/bandeja-entrada.html">Bandeja de Entrada</a>.</li></ol><p><img src="'+i+'" alt="Asistente de Nueva Solicitud de Firma con la selección de firmantes"></p><p>En la lista de solicitudes verás el <strong>estado</strong> de cada una, <strong>quién la asignó</strong>, la <strong>fecha de creación</strong> y la <strong>fecha límite</strong>. Podrás ver cuántas personas ya firmaron y cuántas están <strong>pendientes</strong>. Si una solicitud ya no corresponde, puedes <strong>cancelarla</strong>.</p><blockquote><p>💡 Tú también puedes firmar desde aquí cuando seas uno de los firmantes: se abre la ventana <strong>Confirmar Firma Digital</strong> y se te pedirá tu <strong>PIN de 4 dígitos</strong>.</p></blockquote><h2 id="firmas-offline-—-recolectar-firmas-sin-internet" tabindex="-1">Firmas Offline — recolectar firmas sin internet <a class="header-anchor" href="#firmas-offline-—-recolectar-firmas-sin-internet" aria-label="Permalink to &quot;Firmas Offline — recolectar firmas sin internet&quot;">​</a></h2><p>En muchas obras no hay buena señal. Las <strong>Firmas Offline</strong> te permiten juntar las firmas de los trabajadores <strong>sin conexión</strong> y luego <strong>sincronizarlas</strong> cuando vuelvas a tener internet.</p><ol><li>Entra a <strong>Firmas Offline</strong> y haz clic en <strong>Nueva Solicitud Offline</strong>.</li><li>Define el documento y recolecta las firmas de los presentes (cada uno con su PIN), todo sin necesidad de conexión.</li><li>Cuando recuperes la señal, la plataforma <strong>sincroniza</strong> automáticamente las firmas recolectadas con el sistema.</li></ol><p>Cada solicitud offline muestra su <strong>estado de sincronización</strong>, para que sepas cuáles ya se subieron y cuáles están pendientes de sincronizar.</p><blockquote><p>📶 Las firmas offline se guardan <strong>en tu dispositivo</strong> hasta que sincronizan. No cierres sesión ni borres los datos del navegador antes de sincronizar, o podrías perderlas.</p></blockquote><h2 id="validez-legal-de-la-firma-con-pin" tabindex="-1">Validez legal de la firma con PIN <a class="header-anchor" href="#validez-legal-de-la-firma-con-pin" aria-label="Permalink to &quot;Validez legal de la firma con PIN&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Consulta legal en curso</p><p>La validez jurídica del PIN como firma electrónica ante un fiscalizador del DS 44 está siendo evaluada con la Dirección del Trabajo. La funcionalidad opera con normalidad y deja trazabilidad completa, pero <strong>por ahora no debe usarse como única prueba legal</strong> hasta tener la respuesta oficial. Más detalle en <a href="/manual/ds44/firmas-digitales.html">Firmas digitales y DS44</a>.</p></div><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Dónde defino o cambio mi PIN?</strong> Tu PIN se establece al activar tu cuenta. Puedes cambiarlo desde la configuración de tu perfil. Si lo olvidaste, un administrador puede ayudarte a restablecerlo.</p><p><strong>Olvidé mi PIN y no puedo firmar.</strong> Contacta a un administrador de tu empresa para que te ayude a restablecerlo. Por seguridad, nadie más puede ver tu PIN actual.</p><p><strong>Firmé pero el documento sigue apareciendo como pendiente para otros.</strong> Cada persona firma por separado. El documento se considera completo cuando <strong>todos</strong> los firmantes asignados firmaron. Tu parte ya está; faltan los demás.</p><p><strong>Me equivoqué al firmar un documento.</strong> Las firmas quedan registradas para garantizar la trazabilidad. Si firmaste por error, informa a un administrador o prevencionista: una firma puede quedar marcada como <strong>disputada</strong> para dejar constancia.</p><p><strong>¿Qué es el &quot;token de verificación&quot;?</strong> Es un código único que se genera con cada firma. Sirve para comprobar después que la firma es auténtica y no fue alterada. No necesitas hacer nada con él en el uso diario.</p><p><strong>Estoy en terreno sin señal. ¿Puedo igual juntar firmas?</strong> Sí, para eso están las <strong>Firmas Offline</strong>. Recolectas las firmas sin conexión y se sincronizan solas cuando vuelvas a tener internet.</p><p><strong>¿Quién puede crear solicitudes de firma?</strong> Los roles de gestión (Administrador, Prevencionista, Jefe de Obra, Supervisor según el caso). Un Trabajador normalmente solo firma lo que le solicitan. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p>',31)])])}const h=e(t,[["render",l]]);export{f as __pageData,h as default};
